from __future__ import annotations

from pathlib import Path

import click

from .formatting import format_duration, format_hours, table
from .parsing import RowParseError, parse_file, parse_since_date
from .store import (
    connect,
    default_db_path,
    failure_jobs,
    failure_rates,
    trailing_top_users,
    upsert_jobs,
    usage_by,
)


@click.group()
@click.option(
    "--db",
    "db_path",
    type=click.Path(path_type=Path, dir_okay=False),
    default=None,
    help="SQLite database path. Defaults to ~/.jobwatch/jobs.db.",
)
@click.pass_context
def main(ctx: click.Context, db_path: Path | None) -> None:
    ctx.ensure_object(dict)
    ctx.obj["db_path"] = db_path or default_db_path()


@main.command()
@click.argument("file", type=click.Path(path_type=Path, exists=True, dir_okay=False))
@click.pass_context
def ingest(ctx: click.Context, file: Path) -> None:
    try:
        result = parse_file(file)
    except RowParseError as exc:
        raise click.ClickException(str(exc)) from exc

    conn = connect(ctx.obj["db_path"])
    with conn:
        upserted = upsert_jobs(conn, result.records)
    conn.close()

    click.echo(
        f"ingested {upserted} jobs "
        f"({result.skipped_steps} steps ignored, {result.malformed_rows} malformed rows skipped)"
    )
    if result.malformed_ratio > 0.10:
        raise click.ClickException(
            f"malformed rows exceeded 10% ({result.malformed_rows}/{result.total_rows})"
        )


@main.group()
def report() -> None:
    """Render reports from stored jobs."""


@report.command()
@click.option("--since", required=True, help="ISO date or datetime lower bound.")
@click.option(
    "--by",
    "group_by",
    type=click.Choice(["user", "partition"]),
    default="user",
    show_default=True,
)
@click.pass_context
def usage(ctx: click.Context, since: str, group_by: str) -> None:
    try:
        since_value = parse_since_date(since)
    except ValueError as exc:
        raise click.ClickException(str(exc)) from exc
    conn = connect(ctx.obj["db_path"])
    rows = usage_by(conn, since_value, group_by)
    conn.close()
    body = [
        [row["label"], row["jobs"], format_hours(row["cpu_hours"]), format_hours(row["gpu_hours"])]
        for row in rows
    ]
    click.echo(table([group_by.capitalize(), "Jobs", "CPU-hours", "GPU-hours"], body))


@report.command()
@click.option("--since", required=True, help="ISO date or datetime lower bound.")
@click.pass_context
def failures(ctx: click.Context, since: str) -> None:
    try:
        since_value = parse_since_date(since)
    except ValueError as exc:
        raise click.ClickException(str(exc)) from exc
    conn = connect(ctx.obj["db_path"])
    jobs = failure_jobs(conn, since_value)
    rates = failure_rates(conn, since_value)
    conn.close()

    rows = [
        [
            row["job_id"],
            row["user"],
            row["partition"],
            row["state"],
            format_duration(row["elapsed_seconds"]),
            row["exit_code"],
        ]
        for row in jobs
    ]
    click.echo(table(["JobID", "User", "Partition", "State", "Elapsed", "ExitCode"], rows))
    if rates:
        summary = "; ".join(
            f"{rate.partition}: {rate.failures}/{rate.total} ({rate.rate * 100:.1f}%)"
            for rate in rates
        )
    else:
        summary = "no jobs in range"
    click.echo(f"Failure rate by partition: {summary}")


@main.command()
@click.option("--n", default=10, show_default=True, type=click.IntRange(min=1))
@click.pass_context
def top(ctx: click.Context, n: int) -> None:
    conn = connect(ctx.obj["db_path"])
    since, newest, rows = trailing_top_users(conn, n)
    conn.close()
    body = [
        [row["label"], row["jobs"], format_hours(row["gpu_hours"]), format_hours(row["cpu_hours"])]
        for row in rows
    ]
    click.echo(table(["User", "Jobs", "GPU-hours", "CPU-hours"], body))
    if since and newest:
        click.echo(f"Window: {since} to {newest}")
    else:
        click.echo("Window: no records")


if __name__ == "__main__":
    main()

